input.command:
cd REDACTED && mkdir -p qr && python3 - <<'EOF'
import fitz, cv2, numpy as np, glob, os
base='/Users/leonardodias/arvor/PNAD/data/originals/tse_qrbu_2026/exemplos'
det=cv2.QRCodeDetector()
for pdf in sorted(glob.glob(base+'/**/*.pdf', recursive=True)):
    doc=fitz.open(pdf)
    found=[]
    for i,page in enumerate(doc):
        pix=page.get_pixmap(dpi=300)
        img=np.frombuffer(pix.samples,dtype=np.uint8).reshape(pix.h,pix.w,pix.n)
        if pix.n==4: img=cv2.cvtColor(img,cv2.COLOR_RGBA2BGR)
        elif pix.n==3: img=cv2.cvtColor(img,cv2.COLOR_RGB2BGR)
        out=f"qr/{os.path.basename(pdf)[:-4]}_p{i+1}.png"; cv2.imwrite(out,img)
        ok,decoded,points,_=det.detectAndDecodeMulti(img)
        if ok:
            for d in decoded:
                if d: found.append(d[:40])
    print(os.path.basename(pdf), len(doc), 'pages; cv2 decoded:', len(found), found[:6])
EOF

